import { AdminPage } from "@/components/admin-page";

export default function Page() {
  return <AdminPage />;
}

"use client";

import { FilterIcon } from "lucide-react";
import { useState } from "react";
import {
  activeCount,
  defaultDirection,
  directionLabel,
  FILTERS,
  hasActiveFilters,
  OPTIONS,
  type OptionKey,
  SORT_KEYS,
  type SortState,
  sortLabel,
  type UserFilters,
  type UserSortKey,
} from "@/components/admin-filters";
import {
  Bound,
  DrilldownList,
  DrilldownRow,
  FilterOption,
  Options,
  StepHeader,
} from "@/components/drawer-parts";
import { directionsFor, type SortDirection } from "@/components/sort";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import { RadioGroup } from "@/components/ui/radio-group";
import {
  Stepper,
  StepperContent,
  StepperStep,
  useStepper,
} from "@/components/ui/stepper";

interface AdminFiltersDrawerProps {
  filters: UserFilters;
  onChange: (patch: Partial<UserFilters>) => void;
  onClear: () => void;
  onSortChange: (sort: SortState) => void;
  sort: SortState;
}

/** The single-select filters, in `FILTERS` order; Created and Sort follow. */
const OPTION_STEPS: readonly OptionKey[] = [
  "role",
  "status",
  "seats",
  "twoFactor",
];

/**
 * The phone half of the users toolbar — the same bottom sheet and `Stepper`
 * drilldown as the payments one, because the two tables are one design.
 *
 * Desktop has the pills; below `sm` they would wrap into a column that buries
 * the table, so the whole filter set folds in here: a menu of "label + current
 * value" rows that each open one screen. The rows come from `FILTERS`, the same
 * descriptors the pills read, so a row and its pill cannot disagree.
 *
 * No `swipeDirection`: the primitive's default is `down`, which supplies the
 * bottom-sheet geometry and the drag handle.
 *
 * Filters apply live; `Apply` only dismisses. There is no draft state to
 * reconcile, and on a large phone the table is visible behind the sheet.
 */
export function AdminFiltersDrawer({
  filters,
  onChange,
  onClear,
  onSortChange,
  sort,
}: AdminFiltersDrawerProps) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const count = activeCount(filters);

  return (
    <Drawer
      onOpenChange={(isOpen) => {
        setOpen(isOpen);
        if (!isOpen) {
          setStep(0);
        }
      }}
      open={open}
    >
      {/* The count is on the trigger because the pills are hidden at this
          width — without it a filtered table gives no sign of being filtered.
          Sort is deliberately not counted: it is not a filter, and a badge that
          ticks up when you reorder a column is lying. */}
      <DrawerTrigger render={<Button size="sm" variant="outline" />}>
        <FilterIcon className="size-4" />
        Filters
        {count > 0 && <Badge variant="secondary">{count}</Badge>}
      </DrawerTrigger>
      <DrawerContent>
        <div className="mx-auto w-full max-w-sm">
          <Stepper onValueChange={setStep} value={step}>
            <StepperContent>
              <StepperStep>
                <DrawerHeader>
                  <DrawerTitle className="text-center">Filters</DrawerTitle>
                </DrawerHeader>
                <UserFilterMenu filters={filters} sort={sort} />
                <DrawerFooter>
                  {hasActiveFilters(filters) && (
                    <Button
                      className="w-full"
                      onClick={onClear}
                      variant="ghost"
                    >
                      Clear all
                    </Button>
                  )}
                  <Button className="w-full" onClick={() => setOpen(false)}>
                    Apply
                  </Button>
                </DrawerFooter>
              </StepperStep>

              {OPTION_STEPS.map((key) => (
                <StepperStep key={key}>
                  <StepHeader
                    onBack={() => setStep(0)}
                    title={FILTERS.find((def) => def.key === key)?.label ?? key}
                  />
                  <Options
                    onValueChange={(value) => onChange({ [key]: value })}
                    value={filters[key]}
                  >
                    {OPTIONS[key].map((option) => (
                      <FilterOption
                        key={option.value}
                        label={option.label}
                        value={option.value}
                      />
                    ))}
                  </Options>
                </StepperStep>
              ))}

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Created" />
                <div className="grid grid-cols-2 gap-3 px-4 pb-4">
                  <Bound
                    id="users-drawer-created-after"
                    label="After"
                    onChange={(value) => onChange({ createdAfter: value })}
                    type="date"
                    value={filters.createdAfter}
                  />
                  <Bound
                    id="users-drawer-created-before"
                    label="Before"
                    onChange={(value) => onChange({ createdBefore: value })}
                    type="date"
                    value={filters.createdBefore}
                  />
                </div>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Sort" />
                <div className="pb-4">
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted"
                    onValueChange={(value) => {
                      if (value) {
                        const key = value as UserSortKey;
                        onSortChange({ direction: defaultDirection(key), key });
                      }
                    }}
                    value={sort.key}
                  >
                    {SORT_KEYS.map((option) => (
                      <FilterOption
                        key={option.id}
                        label={option.label}
                        value={option.id}
                      />
                    ))}
                  </RadioGroup>
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted border-border-muted border-t"
                    onValueChange={(value) => {
                      if (value) {
                        onSortChange({
                          direction: value as SortDirection,
                          key: sort.key,
                        });
                      }
                    }}
                    value={sort.direction}
                  >
                    {directionsFor(defaultDirection(sort.key)).map(
                      (direction) => (
                        <FilterOption
                          key={direction}
                          label={directionLabel(sort.key, direction)}
                          value={direction}
                        />
                      )
                    )}
                  </RadioGroup>
                </div>
              </StepperStep>
            </StepperContent>
          </Stepper>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

/**
 * The drilldown menu, generated from the descriptors so a row and its step
 * cannot disagree about their order. Sort is appended by hand because it is
 * not a filter and is not in `FILTERS`.
 */
function UserFilterMenu({
  filters,
  sort,
}: {
  filters: UserFilters;
  sort: SortState;
}) {
  const { goTo } = useStepper();
  const items = [
    ...FILTERS.map((def) => ({
      key: def.key as string,
      label: def.label,
      value: def.value(filters) ?? def.empty,
    })),
    { key: "sort", label: "Sort", value: sortLabel(sort) },
  ];

  return (
    <DrilldownList>
      {items.map((item, index) => (
        <DrilldownRow
          key={item.key}
          label={item.label}
          // Step 0 is the menu itself, so the first row is step 1.
          onClick={() => goTo(index + 1)}
          value={item.value}
        />
      ))}
    </DrilldownList>
  );
}

import { type CsvColumn, toCsv } from "@/components/csv";
import {
  addableKeys as addableKeysOf,
  visibleKeys as visibleKeysOf,
} from "@/components/filter-row";
import {
  type Role,
  type Status,
  statusLabels,
  type User,
} from "@/components/mock-admin";
import type {
  SortState as BaseSortState,
  SortDirection,
} from "@/components/sort";
import {
  oneOf,
  pageFromParams,
  pageToParams,
  sortFromParam,
  sortToParam,
} from "@/components/url-params";
import type { DataTableQuery } from "@/components/use-data-table";

/**
 * The users table's filter and sort vocabulary, owned in one place.
 *
 * The pills, the phone drawer, the URL and the page all need the same option
 * lists and labels. One owner, imported each way, is what keeps an option
 * added to one of them from going missing in another. It is the same shape as
 * `payment-filters.ts`, so both toolbars are one design over two vocabularies.
 */

export type RoleFilter = "all" | Role;
export type StatusFilter = "all" | Status;
export type SeatsFilter = "all" | "none" | "one" | "many";
export type TwoFactorFilter = "all" | "off" | "on";

export const ROLES: readonly Role[] = ["Admin", "Billing", "Member", "Viewer"];
export const STATUSES: readonly Status[] = ["active", "invited", "suspended"];

/** Shared by the table's Status cell and the detail view, so they cannot drift. */
export const STATUS_VARIANT: Record<
  Status,
  "default" | "outline" | "secondary"
> = {
  active: "secondary",
  invited: "outline",
  suspended: "outline",
};

export interface UserFilters {
  createdAfter: string;
  createdBefore: string;
  role: RoleFilter;
  search: string;
  seats: SeatsFilter;
  status: StatusFilter;
  twoFactor: TwoFactorFilter;
}

export const EMPTY_FILTERS: UserFilters = {
  createdAfter: "",
  createdBefore: "",
  role: "all",
  search: "",
  seats: "all",
  status: "all",
  twoFactor: "all",
};

/**
 * Each single-select filter's options, `All` first. The pills and the drawer
 * both list these, so the two cannot offer different choices.
 *
 * The unset value reads as a bare "All" because the pill already says which
 * dimension it belongs to — "Role: All roles" would say it twice.
 */
export const OPTIONS = {
  role: [
    { label: "All", value: "all" },
    ...ROLES.map((role) => ({ label: role, value: role })),
  ],
  seats: [
    { label: "All", value: "all" },
    { label: "No seats", value: "none" },
    { label: "One seat", value: "one" },
    { label: "More than one", value: "many" },
  ],
  status: [
    { label: "All", value: "all" },
    ...STATUSES.map((status) => ({
      label: statusLabels[status],
      value: status,
    })),
  ],
  twoFactor: [
    { label: "All", value: "all" },
    { label: "Enabled", value: "on" },
    { label: "Not enabled", value: "off" },
  ],
} as const satisfies Record<
  "role" | "seats" | "status" | "twoFactor",
  readonly { label: string; value: string }[]
>;

export type OptionKey = keyof typeof OPTIONS;

function optionLabel(key: OptionKey, value: string): string | null {
  return value === "all"
    ? null
    : (OPTIONS[key].find((option) => option.value === value)?.label ?? null);
}

/** An open-ended range still has to say which end it is open at. */
function rangeValue(after: string, before: string): string | null {
  if (after && before) {
    return `${after} – ${before}`;
  }
  if (after) {
    return `from ${after}`;
  }
  if (before) {
    return `to ${before}`;
  }
  return null;
}

// ---------------------------------------------------------------------------
// The pills
// ---------------------------------------------------------------------------

export type FilterKey = "created" | "role" | "seats" | "status" | "twoFactor";

export interface FilterDef {
  /** The patch that resets this filter. */
  clear: Partial<UserFilters>;
  /** What the pill reads when nothing is set. */
  empty: string;
  key: FilterKey;
  /** The dimension, shown muted ahead of the value. */
  label: string;
  /** The value, or `null` when the filter is unset. */
  value: (filters: UserFilters) => string | null;
}

/**
 * One descriptor per filter, and the only place a filter is declared. The
 * pills, the drawer's rows and steps, the active count and the URL all derive
 * from this list.
 */
export const FILTERS: readonly FilterDef[] = [
  {
    clear: { role: "all" },
    empty: "All",
    key: "role",
    label: "Role",
    value: (f) => optionLabel("role", f.role),
  },
  {
    clear: { status: "all" },
    empty: "All",
    key: "status",
    label: "Status",
    value: (f) => optionLabel("status", f.status),
  },
  {
    clear: { seats: "all" },
    empty: "All",
    key: "seats",
    label: "Seats",
    value: (f) => optionLabel("seats", f.seats),
  },
  {
    clear: { twoFactor: "all" },
    empty: "All",
    key: "twoFactor",
    label: "Two-factor",
    value: (f) => optionLabel("twoFactor", f.twoFactor),
  },
  {
    clear: { createdAfter: "", createdBefore: "" },
    empty: "Any",
    key: "created",
    label: "Created",
    value: (f) => rangeValue(f.createdAfter, f.createdBefore),
  },
];

/** The two cuts people take first; the rest are added on demand. */
export const DEFAULT_KEYS: readonly FilterKey[] = ["role", "status"];

export function filterDef(key: FilterKey): FilterDef {
  const def = FILTERS.find((item) => item.key === key);
  if (!def) {
    throw new Error(`Unknown filter: ${key}`);
  }
  return def;
}

export function visibleKeys(
  filters: UserFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  return visibleKeysOf(FILTERS, filters, added);
}

export function addableKeys(
  filters: UserFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  return addableKeysOf(FILTERS, filters, added);
}

/** How many filters hold a value — the phone drawer trigger's badge. */
export function activeCount(filters: UserFilters): number {
  return FILTERS.filter((def) => def.value(filters) !== null).length;
}

/** Whether anything at all is applied, search included. */
export function hasActiveFilters(filters: UserFilters): boolean {
  return Boolean(filters.search.trim()) || activeCount(filters) > 0;
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

type UserMatcher = (user: User, filters: UserFilters) => boolean;

/** One predicate per filter, each returning `true` when the filter is unset. */
const MATCHERS: readonly UserMatcher[] = [
  (user, filters) => {
    const query = filters.search.trim().toLowerCase();
    return (
      !query ||
      user.name.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query)
    );
  },
  (user, filters) => filters.role === "all" || user.role === filters.role,
  (user, filters) => filters.status === "all" || user.status === filters.status,
  (user, filters) => {
    if (filters.seats === "all") {
      return true;
    }
    if (filters.seats === "none") {
      return user.seats === 0;
    }
    return filters.seats === "one" ? user.seats === 1 : user.seats > 1;
  },
  (user, filters) =>
    filters.twoFactor === "all" ||
    user.twoFactor === (filters.twoFactor === "on"),
  // `createdAt` is an ISO date, so it compares as a string.
  (user, filters) =>
    !filters.createdAfter || user.createdAt >= filters.createdAfter,
  (user, filters) =>
    !filters.createdBefore || user.createdAt <= filters.createdBefore,
];

export function matchesUserFilters(user: User, filters: UserFilters): boolean {
  return MATCHERS.every((matches) => matches(user, filters));
}

// ---------------------------------------------------------------------------
// Sort
// ---------------------------------------------------------------------------

export type UserSortKey = "id" | "lastActive" | "name" | "role" | "seats";

/**
 * Always set, like the payments sort. The "Unsorted" option this replaces
 * meant fixture order, which is no order anyone asked for, and it gave the
 * headers a third click that undid the second.
 */
export type SortState = BaseSortState<UserSortKey>;

export const SORT_KEYS: readonly { id: UserSortKey; label: string }[] = [
  { id: "name", label: "Name" },
  { id: "role", label: "Role" },
  { id: "seats", label: "Seats" },
  { id: "lastActive", label: "Last active" },
  { id: "id", label: "ID" },
];

/**
 * What a direction means for the column it applies to. "Ascending" is
 * accurate and says nothing — "A–Z" and "Newest first" say what you will see.
 */
const DIRECTION_LABELS: Record<UserSortKey, Record<SortDirection, string>> = {
  id: { asc: "First added", desc: "Last added" },
  lastActive: { asc: "Oldest first", desc: "Newest first" },
  name: { asc: "A–Z", desc: "Z–A" },
  role: { asc: "A–Z", desc: "Z–A" },
  seats: { asc: "Fewest first", desc: "Most first" },
};

export function directionLabel(
  key: UserSortKey,
  direction: SortDirection
): string {
  return DIRECTION_LABELS[key][direction];
}

/**
 * The direction a column takes when it is first chosen, from the menu or a
 * header. Names read forwards; counts and recency are asked about from the
 * large end.
 */
export function defaultDirection(key: UserSortKey): SortDirection {
  return key === "name" || key === "role" ? "asc" : "desc";
}

export const DEFAULT_SORT: SortState = { direction: "asc", key: "name" };

/** "Name (A–Z)" — the column, then what the order means for it. */
export function sortLabel(sort: SortState): string {
  const key = SORT_KEYS.find((option) => option.id === sort.key)?.label;
  return `${key} (${directionLabel(sort.key, sort.direction)})`;
}

const RELATIVE = /^(\d+|an?) (minute|hour|day|week|month|year)s? ago$/;
const MINUTES = {
  day: 1440,
  hour: 60,
  minute: 1,
  month: 43_200,
  week: 10_080,
  year: 525_600,
} as const;

/**
 * How long ago "Last active" was, in minutes, or `null` for "never".
 *
 * The fixture stores the text the table shows — "2 hours ago" — rather than a
 * timestamp, and that text does not sort: "yesterday" comes after "5 minutes
 * ago" alphabetically. A real table sorts on the timestamp behind the label.
 */
export function minutesAgo(text: string): number | null {
  if (text === "never") {
    return null;
  }
  if (text === "yesterday") {
    return MINUTES.day;
  }
  const match = RELATIVE.exec(text);
  if (!match) {
    return null;
  }
  const count = Number.isNaN(Number(match[1])) ? 1 : Number(match[1]);
  return count * MINUTES[match[2] as keyof typeof MINUTES];
}

/**
 * Users who have never been active have no recency to order by, so they sink
 * to the end in both directions — the same rule as an unfinished payment.
 */
export function sortUsers(rows: readonly User[], sort: SortState): User[] {
  const factor = sort.direction === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    if (sort.key === "lastActive") {
      const left = minutesAgo(a.lastActive);
      const right = minutesAgo(b.lastActive);
      if (left === null || right === null) {
        return Number(left === null) - Number(right === null);
      }
      // Fewer minutes ago is newer, so "Newest first" (desc) is ascending
      // minutes.
      return (right - left) * factor;
    }
    if (sort.key === "seats") {
      return (a.seats - b.seats) * factor;
    }
    return a[sort.key].localeCompare(b[sort.key]) * factor;
  });
}

// ---------------------------------------------------------------------------
// URL
// ---------------------------------------------------------------------------

export const PAGE_SIZES = [5, 10, 20, 50] as const;
export const DEFAULT_PAGE_SIZE = 5;

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The table's query as URL parameters, defaults left out. */
export function usersToParams(
  query: DataTableQuery<UserFilters, UserSortKey>
): Record<string, string> {
  const f = query.filters;
  return {
    q: f.search,
    role: f.role === "all" ? "" : f.role,
    status: f.status === "all" ? "" : f.status,
    seats: f.seats === "all" ? "" : f.seats,
    twoFactor: f.twoFactor === "all" ? "" : f.twoFactor,
    from: f.createdAfter,
    to: f.createdBefore,
    sort: sortToParam(query.sort, DEFAULT_SORT),
    ...pageToParams(query.pageIndex, query.pageSize, DEFAULT_PAGE_SIZE),
  };
}

/** The inverse, validating every value; anything unrecognised is dropped. */
export function usersFromParams(
  params: URLSearchParams
): Partial<DataTableQuery<UserFilters, UserSortKey>> {
  const date = (key: string) => {
    const value = params.get(key) ?? "";
    return ISO_DATE.test(value) ? value : "";
  };
  const option = <K extends OptionKey>(key: K) =>
    oneOf(
      params.get(key),
      OPTIONS[key].map((item) => item.value),
      "all"
    );

  return {
    filters: {
      createdAfter: date("from"),
      createdBefore: date("to"),
      role: option("role") as RoleFilter,
      search: params.get("q") ?? "",
      seats: option("seats") as SeatsFilter,
      status: option("status") as StatusFilter,
      twoFactor: option("twoFactor") as TwoFactorFilter,
    },
    sort: sortFromParam(
      params.get("sort"),
      SORT_KEYS.map((key) => key.id)
    ),
    ...pageFromParams(params, PAGE_SIZES),
  };
}

// ---------------------------------------------------------------------------
// Export
// ---------------------------------------------------------------------------

const CSV_COLUMNS: readonly CsvColumn<User>[] = [
  ["User ID", (u) => u.id],
  ["Name", (u) => u.name],
  ["Email", (u) => u.email],
  ["Role", (u) => u.role],
  ["Status", (u) => u.status],
  ["Seats", (u) => String(u.seats)],
  ["Two-factor", (u) => (u.twoFactor ? "on" : "off")],
  ["Created", (u) => u.createdAt],
  ["Last sign-in", (u) => u.lastSignIn],
];

/** Raw values, as the payments export writes them: ids, not labels. */
export function toUsersCsv(rows: readonly User[]): string {
  return toCsv(CSV_COLUMNS, rows);
}

"use client";

import {
  CopyIcon,
  DownloadIcon,
  EyeIcon,
  MoreHorizontalIcon,
} from "lucide-react";
import { type ReactNode, useState } from "react";
import { AdminPaymentsToolbar } from "@/components/admin-payments-toolbar";
import { downloadCsv } from "@/components/csv";
import { FilteredEmpty } from "@/components/filtered-empty";
import {
  formatAmount,
  PAYMENT_STATUS_VARIANT,
  type Payment,
  paymentStatusLabels,
  payments,
  paymentTypeLabels,
  truncateId,
} from "@/components/mock-payments";
import {
  defaultDirection,
  hasActiveFilters,
  PAGE_SIZES,
  type PaymentSortKey,
  toPaymentsCsv,
} from "@/components/payment-filters";
import { ResultSummary } from "@/components/result-summary";
import { SkeletonRows } from "@/components/skeleton-rows";
import { SortableHead } from "@/components/sort-menu";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { CopyButton } from "@/components/ui/copy-button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  SelectionBar,
  SelectionBarButton,
  SelectionBarClose,
  SelectionBarGroup,
  SelectionBarLabel,
} from "@/components/ui/selection-bar";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  TablePagination,
  TablePaginationButtons,
  TablePaginationControls,
  TablePaginationInfo,
  TablePaginationPageSize,
  TablePaginationStatus,
} from "@/components/ui/table-pagination";
import type {
  PaymentColumnId,
  PaymentsTableState,
} from "@/components/use-payments-table";

interface PaymentColumn {
  cell: (row: Payment) => ReactNode;
  /** Classes for the body cell. */
  className?: string;
  id: PaymentColumnId;
  label: string;
  numeric?: boolean;
  /** Present on the columns that sort. */
  sortKey?: PaymentSortKey;
}

/**
 * The columns a person can show or hide, in order. The payment id, the
 * selection checkbox and the actions are not here: they identify and act on a
 * row, so they are always on.
 */
const COLUMNS: readonly PaymentColumn[] = [
  {
    cell: (row) => <span className="truncate">{row.playerEmail}</span>,
    id: "playerEmail",
    label: "Player",
    sortKey: "playerEmail",
  },
  {
    // The raw string rides along, so a test can read the value the sort used
    // rather than parsing the formatted one back.
    cell: (row) => (
      <span data-amount={row.amount}>
        {formatAmount(row.amount, row.currency)}
      </span>
    ),
    id: "amount",
    label: "Amount",
    numeric: true,
    sortKey: "amount",
  },
  {
    cell: (row) => <Badge variant="outline">{row.currency}</Badge>,
    id: "currency",
    label: "Currency",
  },
  {
    cell: (row) => (
      <Badge variant="outline">{paymentTypeLabels[row.type]}</Badge>
    ),
    id: "type",
    label: "Type",
  },
  {
    cell: (row) => (
      <Badge variant={PAYMENT_STATUS_VARIANT[row.status]}>
        {paymentStatusLabels[row.status]}
      </Badge>
    ),
    id: "status",
    label: "Status",
    sortKey: "status",
  },
  {
    cell: (row) => row.createdAt,
    className: "text-muted-foreground",
    id: "createdAt",
    label: "Created",
    sortKey: "createdAt",
  },
  {
    cell: (row) => row.finishedAt ?? "-",
    className: "text-muted-foreground",
    id: "finishedAt",
    label: "Finished",
    sortKey: "finishedAt",
  },
];

const PAYMENT_COLUMNS = COLUMNS.map(({ id, label }) => ({ id, label }));

export function AdminPaymentsTable({
  onOpenPayment,
  table,
}: {
  onOpenPayment: (id: string) => void;
  table: PaymentsTableState;
}) {
  const { loading, result, selected } = table;
  const visible = COLUMNS.filter(
    (column) => !table.hiddenColumns.has(column.id)
  );
  const allOnPageSelected =
    result.page.length > 0 && result.page.every((row) => selected.has(row.id));

  return (
    <>
      <div className="flex w-full flex-col gap-6">
        {/* A real `h1`, and the page's only heading. `CardTitle` renders a div,
            so the section had no heading outline at all — a screen reader
            moving by headings found nothing here. It also sat inside the card,
            which made the panel announce itself rather than the page. */}
        <h1 className="font-semibold text-2xl tracking-tight">Payments</h1>

        <Card variant="outline">
          <CardContent className="flex flex-col gap-4">
            <AdminPaymentsToolbar columns={PAYMENT_COLUMNS} table={table} />

            {/* `aria-busy` is the loading announcement; the skeleton rows
                underneath are hidden from assistive tech. */}
            <Table aria-busy={loading} hoverable>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-10">
                    <Checkbox
                      aria-label="Select all payments on this page"
                      checked={allOnPageSelected}
                      disabled={loading}
                      onCheckedChange={(checked) =>
                        table.togglePage(checked === true)
                      }
                    />
                  </TableHead>
                  <TableHead className="w-[136px]">Payment ID</TableHead>
                  {visible.map((column) =>
                    column.sortKey ? (
                      <SortableHead
                        columnKey={column.sortKey}
                        defaultDirection={defaultDirection}
                        key={column.id}
                        numeric={column.numeric}
                        onSortChange={table.setSort}
                        sort={table.sort}
                      >
                        {column.label}
                      </SortableHead>
                    ) : (
                      // Not sortable, so no `sortDirection` at all — see
                      // `SortableHead`.
                      <TableHead key={column.id} numeric={column.numeric}>
                        {column.label}
                      </TableHead>
                    )
                  )}
                  {/* No visible label: the column is one icon wide, and
                      "Actions" above it would size the column from the header
                      rather than from the control. */}
                  <TableHead className="w-12">
                    <span className="sr-only">Actions</span>
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <SkeletonRows
                    checkbox
                    columns={visible.length + 1}
                    count={result.page.length || table.pageSize}
                  />
                ) : null}
                {!loading && result.page.length === 0 ? (
                  <FilteredEmpty
                    colSpan={visible.length + 3}
                    filtered={hasActiveFilters(table.filters)}
                    noun="payments"
                    onClear={table.clearFilters}
                  />
                ) : null}
                {loading
                  ? null
                  : result.page.map((row) => (
                      <TableRow
                        className="group/row"
                        data-state={
                          selected.has(row.id) ? "selected" : undefined
                        }
                        key={row.id}
                      >
                        <TableCell>
                          <Checkbox
                            aria-label={`Select payment ${truncateId(row.id)}`}
                            checked={selected.has(row.id)}
                            onCheckedChange={() => table.toggleRow(row.id)}
                          />
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1">
                            {/* Middle-truncated: the head and tail are what
                                someone eyeballs against another system, and
                                the full value is one click away on the
                                clipboard or the record. */}
                            <button
                              className="cursor-pointer rounded-sm font-mono text-muted-foreground text-xs hover:underline focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
                              onClick={() => onOpenPayment(row.id)}
                              type="button"
                            >
                              {truncateId(row.id)}
                            </button>
                            <CopyButton size="icon-xs" value={row.id} />
                          </div>
                        </TableCell>
                        {visible.map((column) => (
                          <TableCell
                            className={column.className}
                            data-column={column.id}
                            key={column.id}
                            numeric={column.numeric}
                          >
                            {column.cell(row)}
                          </TableCell>
                        ))}
                        <TableCell>
                          <RowActions
                            onOpen={() => onOpenPayment(row.id)}
                            paymentId={row.id}
                          />
                        </TableCell>
                      </TableRow>
                    ))}
              </TableBody>
            </Table>

            {/* Composed rather than props-driven: the info slot's only
                props-driven content is a selection count, which the
                `SelectionBar` already states — at every width, where this slot
                is `hidden lg:block`. */}
            <TablePagination
              pageCount={result.pageCount}
              pageIndex={table.pageIndex}
            >
              <TablePaginationInfo>
                <ResultSummary
                  noun={["payment", "payments"]}
                  pageIndex={table.pageIndex}
                  pageSize={table.pageSize}
                  rowCount={result.page.length}
                  totalCount={result.total}
                />
              </TablePaginationInfo>
              <TablePaginationControls>
                <TablePaginationPageSize
                  onValueChange={table.setPageSize}
                  options={PAGE_SIZES}
                  value={table.pageSize}
                />
                <TablePaginationStatus
                  pageCount={result.pageCount}
                  pageIndex={table.pageIndex}
                />
                <TablePaginationButtons
                  onPageIndexChange={table.setPageIndex}
                  pageCount={result.pageCount}
                  pageIndex={table.pageIndex}
                />
              </TablePaginationControls>
            </TablePagination>
          </CardContent>
        </Card>
      </div>

      <PaymentSelectionBar onClear={table.clearSelection} selected={selected} />
    </>
  );
}

/**
 * What to do with the rows you ticked. Only actions this block can actually
 * perform: a ledger's real bulk actions — refund, retry, mark reviewed — need a
 * backend, and a button that does nothing is worse than none.
 *
 * It reads from every payment, not the current result, because a selection
 * outlives the filter that was on when you made it.
 */
function PaymentSelectionBar({
  onClear,
  selected,
}: {
  onClear: () => void;
  selected: ReadonlySet<string>;
}) {
  const [copied, setCopied] = useState(false);
  const rows = payments.filter((payment) => selected.has(payment.id));

  return (
    <SelectionBar open={selected.size > 0}>
      <SelectionBarClose onClick={onClear} />
      <SelectionBarGroup>
        <SelectionBarLabel>
          {selected.size} {selected.size === 1 ? "payment" : "payments"}{" "}
          selected
        </SelectionBarLabel>
      </SelectionBarGroup>
      <SelectionBarButton
        onClick={() =>
          downloadCsv("payments-selected.csv", toPaymentsCsv(rows))
        }
      >
        <DownloadIcon />
        Export
      </SelectionBarButton>
      <SelectionBarButton
        onClick={async () => {
          try {
            await navigator.clipboard.writeText(
              rows.map((row) => row.id).join("\n")
            );
            setCopied(true);
            setTimeout(() => setCopied(false), 1500);
          } catch {
            // Insecure context or permission denied; nothing to undo.
          }
        }}
      >
        <CopyIcon />
        {copied ? "Copied" : "Copy IDs"}
      </SelectionBarButton>
    </SelectionBar>
  );
}

/**
 * Row actions, in a trailing menu rather than a hover-revealed button.
 *
 * The button it replaces was unreachable on touch: there is no hover, and
 * `focus-visible:opacity-100` only rescues a keyboard. A ledger is also where
 * per-row actions accumulate — refund, export receipt, open the player — and a
 * menu absorbs those where a row of inline buttons cannot.
 *
 * "Copy payment ID" duplicates the icon button beside the id deliberately:
 * that one is the fast path for a value the table shows cut down, this one is
 * the labelled path for anyone who would not read an unlabelled icon.
 */
function RowActions({
  onOpen,
  paymentId,
}: {
  onOpen: () => void;
  paymentId: string;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="icon-sm" variant="ghost" />}>
        <MoreHorizontalIcon />
        <span className="sr-only">
          Actions for payment {truncateId(paymentId)}
        </span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-44">
        <DropdownMenuGroup>
          <DropdownMenuItem onClick={onOpen}>
            <EyeIcon />
            View details
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={async () => {
              // No "Copied" state to hold — the menu closes on click — so this
              // needs none of what `CopyButton` manages beyond awaiting the
              // write and not throwing where the clipboard is unavailable.
              try {
                await navigator.clipboard.writeText(paymentId);
              } catch {
                // Insecure context or permission denied; nothing to undo.
              }
            }}
          >
            <CopyIcon />
            Copy payment ID
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { DownloadIcon, SearchIcon, XIcon } from "lucide-react";
import { ColumnsMenu } from "@/components/columns-menu";
import { downloadCsv } from "@/components/csv";
import { AddFilterMenu, usePillRow } from "@/components/filter-pills";
import { PaymentFilterPill } from "@/components/payment-filter-pills";
import {
  addableKeys,
  defaultDirection,
  directionLabel,
  filterDef,
  hasActiveFilters,
  SORT_KEYS,
  toPaymentsCsv,
  visibleKeys,
} from "@/components/payment-filters";
import { PaymentFiltersDrawer } from "@/components/payment-filters-drawer";
import { SortMenu } from "@/components/sort-menu";
import { Button } from "@/components/ui/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import type {
  PaymentColumnId,
  PaymentsTableState,
} from "@/components/use-payments-table";

/**
 * Search, then one self-describing pill per filter, then `+ Add filter`; at the
 * far end, how the table is viewed — Columns, Export, Sort.
 *
 * Each pill names its own dimension — `Action: Deposit` rather than `Deposit`
 * — which is what lets the control double as the record of what is applied.
 * That is why there is no chip row underneath: a chip repeating a pill you can
 * already see is a second copy of the same fact, and the two can drift.
 *
 * Six pills at once would wrap before anyone had used one, so the row starts
 * with the two most common cuts and the rest are added on demand. Any pill can
 * come off again. A filter that holds a value always shows its pill
 * regardless — see `visibleKeys`.
 *
 * The right-hand group changes how the rows are shown, not which rows, so it
 * sits apart from the pills and each control names itself — `Sort:` reads as a
 * sort, not one more filter. The headers sort too, and both write the one
 * `sort` state, so a header click moves the menu's check and back.
 *
 * Below `sm` the pills and the right-hand group fold away and the drawer
 * carries the whole filter set, with Sort as its last step. A row of pills
 * becomes a column of pills on a phone, which buries the table it is
 * filtering; a CSV download on a phone lands in a files app nobody opens.
 */
export function AdminPaymentsToolbar({
  columns,
  table,
}: {
  columns: readonly { id: PaymentColumnId; label: string }[];
  table: PaymentsTableState;
}) {
  const { added, filters, patchFilters } = table;
  const row = usePillRow({
    onAdd: table.addFilter,
    onRemove: table.removeFilter,
  });

  return (
    <div className="flex flex-wrap items-center gap-2">
      {/* A floor on the field's width, so a full row wraps its right-hand
          group onto a second line rather than crushing search to a stub. */}
      <InputGroup className="min-w-0 flex-1 sm:min-w-56 sm:max-w-xs" size="sm">
        <InputGroupAddon align="inline-start">
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          aria-label="Search payments by email"
          onChange={(event) => patchFilters({ email: event.target.value })}
          placeholder="Search email…"
          type="search"
          value={filters.email}
        />
      </InputGroup>

      <div
        className="hidden flex-wrap items-center gap-2 sm:flex"
        ref={row.rowRef}
      >
        {visibleKeys(filters, added).map((key) => (
          <PaymentFilterPill
            autoOpen={key === row.opening}
            filters={filters}
            key={key}
            onChange={patchFilters}
            onPin={table.addFilter}
            onRemove={row.remove}
            pillKey={key}
          />
        ))}

        <AddFilterMenu
          items={addableKeys(filters, added).map((key) => ({
            key,
            label: filterDef(key).label,
          }))}
          onAdd={row.add}
        />

        {hasActiveFilters(filters) && (
          // Muted at rest: undoing everything is the least likely thing you
          // came here to do, and it sits next to the control you probably did.
          // It brightens on hover so it still answers when pointed at.
          <Button
            className="text-muted-foreground hover:text-foreground"
            onClick={table.clearFilters}
            size="sm"
            variant="ghost"
          >
            <XIcon />
            Clear all
          </Button>
        )}
      </div>

      <div className="hidden shrink-0 items-center gap-2 sm:ml-auto sm:flex">
        <ColumnsMenu
          columns={columns}
          hidden={table.hiddenColumns}
          onToggle={table.toggleColumn}
        />
        <Button
          disabled={table.loading || table.result.total === 0}
          onClick={() =>
            downloadCsv("payments.csv", toPaymentsCsv(table.result.all))
          }
          size="sm"
          variant="outline"
        >
          <DownloadIcon />
          Export
        </Button>
        <SortMenu
          defaultDirection={defaultDirection}
          directionLabel={directionLabel}
          keys={SORT_KEYS}
          onSortChange={table.setSort}
          sort={table.sort}
        />
      </div>

      <div className="shrink-0 sm:hidden">
        <PaymentFiltersDrawer
          filters={filters}
          onChange={patchFilters}
          onClear={table.clearFilters}
          onSortChange={table.setSort}
          sort={table.sort}
        />
      </div>
    </div>
  );
}

"use client";

import { Bar, BarChart, CartesianGrid, XAxis, YAxis } from "recharts";
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/chart";
import { formatValue } from "@/components/chart-formatters";
import {
  type AdminMetric,
  SIGNUP_SERIES,
  type SignupPoint,
} from "@/components/mock-admin";
import { SeriesLegend, seriesColor } from "@/components/series-legend";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { StatDelta, StatValue } from "@/components/ui/stat";

interface AdminOverviewProps {
  hidden: ReadonlySet<string>;
  metrics: readonly AdminMetric[];
  onToggle: (key: string) => void;
  reducedMotion: boolean;
  signups: readonly SignupPoint[];
}

export function AdminOverview({
  hidden,
  metrics,
  onToggle,
  reducedMotion,
  signups,
}: AdminOverviewProps) {
  const shown = SIGNUP_SERIES.filter((item) => !hidden.has(item.key));

  const config = Object.fromEntries(
    SIGNUP_SERIES.map((item, index) => [
      item.key,
      { color: seriesColor(item, index), label: item.label },
    ])
  );

  return (
    <div className="flex flex-col gap-6">
      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 [&>*]:min-w-0">
        {metrics.map((metric) => (
          <Card key={metric.label} size="sm" variant="outline">
            <CardContent className="flex flex-col gap-1">
              <div className="font-medium text-muted-foreground text-xs">
                {metric.label}
              </div>
              <StatValue>
                {metric.value}
                {metric.delta === null ? null : (
                  <StatDelta direction={metric.direction} value={metric.delta}>
                    {metric.deltaLabel}
                  </StatDelta>
                )}
              </StatValue>
              <div className="text-muted-foreground text-xs">
                {metric.sublabel}
              </div>
            </CardContent>
          </Card>
        ))}
      </section>

      <Card variant="outline">
        <CardHeader>
          {/* Semibold rather than CardTitle's default medium. A dashboard panel
              heading competes with a lot of dense content, so it needs more
              weight than a login card's title does -- but the component stays at
              font-medium, in line with every other *Title part in the library. */}
          <CardTitle className="font-semibold">Signups</CardTitle>
          <CardDescription>
            Trial and paid accounts started each month.
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-3">
          <ChartContainer className="h-[240px] w-full" config={config}>
            <BarChart accessibilityLayer data={[...signups]}>
              <CartesianGrid vertical={false} />
              <XAxis
                axisLine={false}
                dataKey="month"
                tickLine={false}
                tickMargin={8}
              />
              <YAxis
                axisLine={false}
                tickFormatter={(value) => formatValue(value, "number")}
                tickLine={false}
                width="auto"
              />
              <ChartTooltip
                content={
                  <ChartTooltipContent
                    formatter={(value, name) => (
                      <div className="flex flex-1 items-center justify-between gap-3">
                        <span className="text-muted-foreground">
                          {config[name as string]?.label ?? name}
                        </span>
                        <span className="font-medium font-mono tabular-nums">
                          {formatValue(value, "number")}
                        </span>
                      </div>
                    )}
                  />
                }
                cursor={false}
              />
              {shown.map((item, index) => (
                <Bar
                  dataKey={item.key}
                  fill={`var(--color-${item.key})`}
                  isAnimationActive={!reducedMotion}
                  key={item.key}
                  // Cap measured against the VISIBLE bands, so hiding the top
                  // series does not leave the stack uncapped.
                  radius={
                    index === shown.length - 1
                      ? ([4, 4, 0, 0] as [number, number, number, number])
                      : 0
                  }
                  stackId="signups"
                  // Matches the panel's real background: `variant="outline"`
                  // has no fill, so a --card seam would be visibly wrong.
                  stroke="var(--background)"
                  strokeWidth={2}
                />
              ))}
            </BarChart>
          </ChartContainer>
          <SeriesLegend
            hidden={hidden}
            onToggle={onToggle}
            series={SIGNUP_SERIES}
          />
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { usersFromParams, usersToParams } from "@/components/admin-filters";
import { AdminOverview } from "@/components/admin-overview";
import { AdminPaymentsTable } from "@/components/admin-payments-table";
import { type AdminSection, AdminSidebar } from "@/components/admin-sidebar";
import { AdminTopbar } from "@/components/admin-topbar";
import { AdminUserDetail } from "@/components/admin-user-detail";
import { AdminUsersTable } from "@/components/admin-users-table";
import { adminMetrics, signupsByMonth, users } from "@/components/mock-admin";
import { payments } from "@/components/mock-payments";
import { PaymentDetailDrawer } from "@/components/payment-detail-drawer";
import {
  paymentsFromParams,
  paymentsToParams,
} from "@/components/payment-filters";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { oneOf } from "@/components/url-params";
import { usePaymentsTable } from "@/components/use-payments-table";
import { useReducedMotion } from "@/components/use-reduced-motion";
import { useUrlState } from "@/components/use-url-state";
import { useUsersTable } from "@/components/use-users-table";

const SECTIONS: readonly AdminSection[] = [
  "overview",
  "users",
  "payments",
  "billing",
  "settings",
];

/** All state lives here; the panels below are presentational. */
export function AdminPage() {
  const reducedMotion = useReducedMotion();

  const [section, setSection] = useState<AdminSection>("overview");
  const [hidden, setHidden] = useState<ReadonlySet<string>>(new Set());
  const usersTable = useUsersTable();
  const [openUserId, setOpenUserId] = useState<string | null>(null);
  const paymentsTable = usePaymentsTable();
  const [openPaymentId, setOpenPaymentId] = useState<string | null>(null);

  // The URL carries the open section and that section's query, so a link
  // opens on the same rows. Only the open section's: a link to a filtered
  // payments view should not also carry a users filter nobody can see.
  useUrlState(
    (params) => {
      const view = oneOf(params.get("view"), SECTIONS, "overview");
      setSection(view);
      if (view === "users") {
        usersTable.restore(usersFromParams(params));
      }
      if (view === "payments") {
        paymentsTable.restore(paymentsFromParams(params));
      }
    },
    {
      view: section === "overview" ? "" : section,
      ...(section === "users" ? usersToParams(usersTable.query) : {}),
      ...(section === "payments" ? paymentsToParams(paymentsTable.query) : {}),
    }
  );

  const openUser = openUserId
    ? (users.find((user) => user.id === openUserId) ?? null)
    : null;

  // `invitedBy` holds the inviter's id, so the record can link to them.
  const inviter = openUser?.invitedBy
    ? (users.find((user) => user.id === openUser.invitedBy) ?? null)
    : null;

  const toggleSeries = (key: string) => {
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  return (
    <SidebarProvider>
      <AdminSidebar
        onSectionChange={(next) => {
          setSection(next);
          setOpenUserId(null);
          setOpenPaymentId(null);
        }}
        section={section}
      />
      {/* min-w-0 is required, not cosmetic. Without it a wide table pushes the
          inset open and the whole document gains a horizontal scrollbar — in
          the app this pattern came from, its absence cost +256px of overflow
          across eight pages. Keystone can bake this into components it owns;
          this one is shadcn's, so it lands at the call site. */}
      <SidebarInset className="min-w-0">
        <AdminTopbar
          detail={openUser?.name}
          onDetailExit={() => setOpenUserId(null)}
          section={section}
        />

        <div className="flex min-w-0 flex-1 flex-col gap-6 p-4 md:p-6">
          {section === "users" && openUser ? (
            <AdminUserDetail
              inviter={inviter}
              onBack={() => setOpenUserId(null)}
              onOpenUser={setOpenUserId}
              user={openUser}
            />
          ) : null}

          {section === "users" && !openUser ? (
            <AdminUsersTable onOpenUser={setOpenUserId} table={usersTable} />
          ) : null}

          {section === "overview" ? (
            <AdminOverview
              hidden={hidden}
              metrics={adminMetrics}
              onToggle={toggleSeries}
              reducedMotion={reducedMotion}
              signups={signupsByMonth}
            />
          ) : null}

          {section === "payments" ? (
            <AdminPaymentsTable
              onOpenPayment={setOpenPaymentId}
              table={paymentsTable}
            />
          ) : null}

          {/* Always mounted, open only while a payment is chosen, so the
              Drawer can play its exit animation rather than vanish with its
              row. Leaving the section clears the choice. */}
          <PaymentDetailDrawer
            onClose={() => setOpenPaymentId(null)}
            payment={
              section === "payments" && openPaymentId
                ? (payments.find((payment) => payment.id === openPaymentId) ??
                  null)
                : null
            }
          />

          {section === "billing" || section === "settings" ? (
            <div className="flex h-[420px] items-center justify-center rounded-xl border border-border border-dashed bg-muted/20 text-muted-foreground text-sm">
              {section === "billing" ? "Billing" : "Settings"} lives here.
            </div>
          ) : null}
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

