interface PaymentFiltersDrawerProps {
  filters: PaymentFilters;
  onChange: (patch: Partial<PaymentFilters>) => void;
  onClear: () => void;
  onSortChange: (sort: SortState) => void;
  sort: SortState;
}

/**
 * The mobile half of the payments toolbar.
 *
 * The same bottom sheet + `Stepper` drilldown the users drawer uses, and for
 * the same reason: a menu of "label + current value" rows that open one screen
 * per filter is how a phone handles a filter set that will not fit, and a
 * block should not answer that question twice in two different ways. This
 * started life as a scrolling column of selects — a desktop panel put on a
 * phone — which is exactly the reinvention the users drawer warns against.
 *
 * No `swipeDirection`: the primitive's default is `down`, which is what
 * supplies the bottom-sheet geometry and the drag handle. No `variant` either
 * — `floating` only applies from `md` up, and this drawer is `sm:hidden`, so
 * it could never have taken effect.
 *
 * Filters apply live; `Apply` only dismisses. Same as the users drawer.
 *
 * Sort is the last row, because the desktop Sort menu is hidden at this width
 * too. It is not counted on the trigger: it is not a filter, and a badge that
 * ticks up when you reorder a column is lying.
 */
export function PaymentFiltersDrawer({
  filters,
  onChange,
  onClear,
  onSortChange,
  sort,
}: PaymentFiltersDrawerProps) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const activeCount = FILTERS.filter(
    (def) => def.value(filters) !== null
  ).length;

  return (
    <Drawer
      onOpenChange={(isOpen) => {
        setOpen(isOpen);
        if (!isOpen) {
          setStep(0);
        }
      }}
      open={open}
    >
      {/* The count is on the trigger because the pills are hidden at this
          width — without it a filtered table gives no sign of being filtered. */}
      <DrawerTrigger render={<Button size="sm" variant="outline" />}>
        <FilterIcon className="size-4" />
        Filters
        {activeCount > 0 && <Badge variant="secondary">{activeCount}</Badge>}
      </DrawerTrigger>
      <DrawerContent>
        <div className="mx-auto w-full max-w-sm">
          <Stepper onValueChange={setStep} value={step}>
            <StepperContent>
              <StepperStep>
                <DrawerHeader>
                  <DrawerTitle className="text-center">Filters</DrawerTitle>
                </DrawerHeader>
                <PaymentFilterMenu filters={filters} sort={sort} />
                <DrawerFooter>
                  {hasActiveFilters(filters) && (
                    <Button
                      className="w-full"
                      onClick={onClear}
                      variant="ghost"
                    >
                      Clear all
                    </Button>
                  )}
                  <Button className="w-full" onClick={() => setOpen(false)}>
                    Apply
                  </Button>
                </DrawerFooter>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Action" />
                <Options
                  onValueChange={(value) =>
                    onChange({ type: value as PaymentFilters["type"] })
                  }
                  value={filters.type}
                >
                  {TYPE_OPTIONS.map((option) => (
                    <FilterOption
                      key={option}
                      label={typeLabel(option)}
                      value={option}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Status" />
                <Options
                  onValueChange={(value) =>
                    onChange({ status: value as PaymentFilters["status"] })
                  }
                  value={filters.status}
                >
                  {STATUS_OPTIONS.map((option) => (
                    <FilterOption
                      key={option}
                      label={statusLabel(option)}
                      value={option}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Currency" />
                <OperatorToggle
                  label="Currency operator"
                  onValueChange={(op) =>
                    onChange({ currencyOp: op as CurrencyOperator })
                  }
                  options={CURRENCY_OPERATORS}
                  value={filters.currencyOp}
                />
                {/* Checkboxes, not radios: this is the one multi-select in the
                    set, so it is the one screen you do not leave per pick. */}
                <div className="divide-y divide-border-muted pb-4">
                  {CURRENCIES.map((currency) => (
                    // biome-ignore lint/a11y/noLabelWithoutControl: control is inside label
                    <label
                      className="flex h-12 cursor-pointer items-center gap-3 px-4"
                      key={currency}
                    >
                      <Checkbox
                        checked={filters.currencies.includes(currency)}
                        onCheckedChange={() =>
                          onChange({
                            currencies: filters.currencies.includes(currency)
                              ? filters.currencies.filter(
                                  (item) => item !== currency
                                )
                              : [...filters.currencies, currency],
                          })
                        }
                      />
                      <span className="text-sm">{currency}</span>
                    </label>
                  ))}
                </div>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Provider" />
                <Options
                  onValueChange={(value) =>
                    onChange({ provider: value as PaymentFilters["provider"] })
                  }
                  value={filters.provider}
                >
                  {PROVIDER_OPTIONS.map((option) => (
                    <FilterOption
                      key={option}
                      label={providerLabel(option)}
                      value={option}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Player" />
                {/* Six operators do not fit a segmented row on a phone, and a
                    native select is the phone's own picker for one-of-many. */}
                <div className="px-4 pb-3">
                  <NativeSelect
                    aria-label="Player operator"
                    onChange={(event) =>
                      onChange({
                        playerOp: event.target.value as PlayerOperator,
                      })
                    }
                    value={filters.playerOp}
                  >
                    {PLAYER_OPERATORS.map((op) => (
                      <NativeSelectOption key={op.value} value={op.value}>
                        {op.label.charAt(0).toUpperCase() + op.label.slice(1)}
                      </NativeSelectOption>
                    ))}
                  </NativeSelect>
                </div>
                <div className="px-4 pb-4">
                  <Bound
                    id="drawer-player"
                    label="Player email"
                    onChange={(value) => onChange({ player: value })}
                    placeholder="e.g. gmail"
                    value={filters.player}
                  />
                </div>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Created" />
                <Bounds>
                  <Bound
                    id="drawer-created-after"
                    label="After"
                    onChange={(value) => onChange({ createdAfter: value })}
                    type="date"
                    value={filters.createdAfter}
                  />
                  <Bound
                    id="drawer-created-before"
                    label="Before"
                    onChange={(value) => onChange({ createdBefore: value })}
                    type="date"
                    value={filters.createdBefore}
                  />
                </Bounds>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Amount" />
                <OperatorToggle
                  label="Amount operator"
                  onValueChange={(op) =>
                    onChange(setAmountOp(op as AmountOperator))
                  }
                  options={AMOUNT_OPERATORS.map((op) => ({
                    label: amountOperatorLabel(op),
                    value: op,
                  }))}
                  value={filters.amountOp}
                />
                {filters.amountOp === "between" ? (
                  <Bounds>
                    <Bound
                      id="drawer-amount-min"
                      label="Min"
                      onChange={(value) => onChange({ amountMin: value })}
                      placeholder="0.00"
                      value={filters.amountMin}
                    />
                    <Bound
                      id="drawer-amount-max"
                      label="Max"
                      onChange={(value) => onChange({ amountMax: value })}
                      placeholder="Any"
                      value={filters.amountMax}
                    />
                  </Bounds>
                ) : (
                  <div className="px-4 pb-4">
                    <Bound
                      id="drawer-amount-value"
                      label="Amount"
                      onChange={(value) =>
                        onChange(
                          filters.amountOp === "lt"
                            ? { amountMax: value }
                            : { amountMin: value }
                        )
                      }
                      placeholder="0.00"
                      value={
                        filters.amountOp === "lt"
                          ? filters.amountMax
                          : filters.amountMin
                      }
                    />
                  </div>
                )}
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Sort" />
                <div className="pb-4">
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted"
                    onValueChange={(value) => {
                      if (value) {
                        const key = value as PaymentSortKey;
                        onSortChange({ direction: defaultDirection(key), key });
                      }
                    }}
                    value={sort.key}
                  >
                    {SORT_KEYS.map((option) => (
                      <FilterOption
                        key={option.id}
                        label={option.label}
                        value={option.id}
                      />
                    ))}
                  </RadioGroup>
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted border-border-muted border-t"
                    onValueChange={(value) => {
                      if (value) {
                        onSortChange({
                          direction: value as SortDirection,
                          key: sort.key,
                        });
                      }
                    }}
                    value={sort.direction}
                  >
                    {directionsFor(defaultDirection(sort.key)).map(
                      (direction) => (
                        <FilterOption
                          key={direction}
                          label={directionLabel(sort.key, direction)}
                          value={direction}
                        />
                      )
                    )}
                  </RadioGroup>
                </div>
              </StepperStep>
            </StepperContent>
          </Stepper>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

const MENU_STEPS = [
  { key: "type", step: 1 },
  { key: "status", step: 2 },
  { key: "currencies", step: 3 },
  { key: "provider", step: 4 },
  { key: "player", step: 5 },
  { key: "created", step: 6 },
  { key: "amount", step: 7 },
] as const;

/** After every filter step, so adding a filter never renumbers it. */
const SORT_STEP = MENU_STEPS.length + 1;

/**
 * The drilldown menu. Every row's value comes from the same `FILTERS`
 * descriptor the desktop pills read, so a row and its pill cannot disagree
 * about what is applied.
 */
function PaymentFilterMenu({
  filters,
  sort,
}: {
  filters: PaymentFilters;
  sort: SortState;
}) {
  const { goTo } = useStepper();

  const items = MENU_STEPS.map(({ key, step }) => {
    const def = filterDef(key);
    const value = def.value(filters);
    // The same operator the pill shows, so `is not` set on a desktop is not
    // invisible on a phone — the row would otherwise read "BTC" for a table
    // that excludes it.
    const operator = value === null ? null : def.operator?.(filters);
    // A row has room the pill does not, so a multi-select says what the
    // number counts rather than leaving a bare "3".
    const shown =
      key === "currencies" && filters.currencies.length > 1
        ? `${filters.currencies.length} selected`
        : (value ?? def.empty);
    return {
      label: def.label,
      step,
      value: operator ? `${operator} ${shown}` : shown,
    };
  });

  return (
    <DrilldownList>
      {items.map((item) => (
        <DrilldownRow
          key={item.step}
          label={item.label}
          onClick={() => goTo(item.step)}
          value={item.value}
        />
      ))}
      <DrilldownRow
        label="Sort"
        onClick={() => goTo(SORT_STEP)}
        value={sortLabel(sort)}
      />
    </DrilldownList>
  );
}

/**
 * A drawer step's operator, as a segmented control above its values: two to
 * four short options fit one row on a phone, where a menu would be a sheet
 * inside a sheet.
 */
function OperatorToggle({
  label,
  onValueChange,
  options,
  value,
}: {
  label: string;
  onValueChange: (value: string) => void;
  options: readonly { label: string; value: string }[];
  value: string;
}) {
  return (
    <div className="px-4 pb-3">
      <ToggleGroup
        aria-label={label}
        className="w-full"
        onValueChange={(next) => {
          // A segmented control always holds one value; pressing the active
          // segment again would otherwise empty it.
          if (next[0]) {
            onValueChange(next[0] as string);
          }
        }}
        size="sm"
        value={[value]}
        variant="outline"
      >
        {options.map((option) => (
          <ToggleGroupItem
            className="flex-1"
            key={option.value}
            value={option.value}
          >
            {option.label}
          </ToggleGroupItem>
        ))}
      </ToggleGroup>
    </div>
  );
}

function Bounds({ children }: { children: ReactNode }) {
  return <div className="grid grid-cols-2 gap-3 px-4 pb-4">{children}</div>;
}

import { type CsvColumn, toCsv } from "@/components/csv";
import {
  addableKeys as addableKeysOf,
  visibleKeys as visibleKeysOf,
} from "@/components/filter-row";
import {
  CURRENCIES,
  type Currency,
  type Payment,
  type PaymentStatus,
  type PaymentType,
  PROVIDERS,
  type Provider,
  paymentStatusLabels,
} from "@/components/mock-payments";
import type {
  SortState as BaseSortState,
  SortDirection,
} from "@/components/sort";
import {
  oneOf,
  pageFromParams,
  pageToParams,
  sortFromParam,
  sortToParam,
} from "@/components/url-params";
import type { DataTableQuery } from "@/components/use-data-table";

/**
 * The payments filter vocabulary, owned in one place.
 *
 * Every filter is a pill that names its own dimension — `Action: Deposit`, not
 * `Deposit`. A bare value turns ambiguous the moment it sits beside another
 * one: is "Deposit" a type or a status? Naming the dimension also lets the
 * control double as the record of what is applied, which is why there is no
 * separate chip row here. A chip repeating a visible pill is a second
 * representation of the same fact, and two representations can disagree.
 *
 * `FILTERS` below is the single source of truth that the toolbar pills, the
 * add-filter menu and the mobile drawer all read.
 */

export type TypeFilter = "all" | PaymentType;
export type StatusFilter = "all" | PaymentStatus;
export type ProviderFilter = "all" | Provider;

/**
 * The operator filters carry their comparison alongside their value, the way
 * Notion's do.
 *
 * Each field gets the operators that mean something for it. Currency is
 * `is` / `is not`, not `contains`: a payment holds exactly one currency, so
 * "contains USDT" would match the same rows as "is USDT" — two operators for
 * one result. `contains` belongs to text, which is where the player filter
 * uses it: "gmail" matches every gmail address.
 */
export type CurrencyOperator = "is" | "isNot";
export type AmountOperator = "between" | "eq" | "gt" | "lt";
export type PlayerOperator =
  | "contains"
  | "endsWith"
  | "is"
  | "isNot"
  | "notContains"
  | "startsWith";

export interface PaymentFilters {
  amountMax: string;
  amountMin: string;
  amountOp: AmountOperator;
  createdAfter: string;
  createdBefore: string;
  currencies: readonly Currency[];
  currencyOp: CurrencyOperator;
  email: string;
  player: string;
  playerOp: PlayerOperator;
  provider: ProviderFilter;
  status: StatusFilter;
  type: TypeFilter;
}

export const EMPTY_FILTERS: PaymentFilters = {
  amountMax: "",
  amountMin: "",
  amountOp: "between",
  createdAfter: "",
  createdBefore: "",
  currencies: [],
  currencyOp: "is",
  email: "",
  player: "",
  playerOp: "contains",
  provider: "all",
  status: "all",
  type: "all",
};

export const STATUS_OPTIONS: readonly StatusFilter[] = [
  "all",
  "completed",
  "in-progress",
  "failed",
];

export const TYPE_OPTIONS: readonly TypeFilter[] = [
  "all",
  "deposit",
  "cashout",
];

export const PROVIDER_OPTIONS: readonly ProviderFilter[] = [
  "all",
  ...PROVIDERS,
];

/**
 * The unset value reads as a bare "All" because the pill already says which
 * dimension it belongs to — "Action: All types" would say it twice.
 */
const TYPE_LABELS: Record<TypeFilter, string> = {
  all: "All",
  cashout: "Cashout",
  deposit: "Deposit",
};

export function typeLabel(type: TypeFilter): string {
  return TYPE_LABELS[type];
}

export function statusLabel(status: StatusFilter): string {
  return status === "all" ? "All" : paymentStatusLabels[status];
}

export function providerLabel(provider: ProviderFilter): string {
  return provider === "all" ? "All" : provider;
}

export const PLAYER_OPERATORS: readonly {
  label: string;
  value: PlayerOperator;
}[] = [
  // Notion's set for text, in Notion's order. `is empty` / `is not empty` are
  // left out: every payment has a player, so both would be constant.
  { label: "is", value: "is" },
  { label: "is not", value: "isNot" },
  { label: "contains", value: "contains" },
  { label: "does not contain", value: "notContains" },
  { label: "starts with", value: "startsWith" },
  { label: "ends with", value: "endsWith" },
];

export const CURRENCY_OPERATORS: readonly {
  label: string;
  value: CurrencyOperator;
}[] = [
  { label: "is", value: "is" },
  { label: "is not", value: "isNot" },
];

export const AMOUNT_OPERATORS: readonly AmountOperator[] = [
  "between",
  "eq",
  "gt",
  "lt",
];

export function amountOperatorLabel(op: AmountOperator): string {
  return AMOUNT_SYMBOLS[op];
}

const AMOUNT_SYMBOLS: Record<AmountOperator, string> = {
  between: "between",
  eq: "=",
  gt: ">",
  lt: "<",
};

/**
 * Switching the amount operator, as a patch.
 *
 * `eq` and `gt` read one bound (`amountMin`), `lt` reads the other
 * (`amountMax`). Without dropping the bound the new operator does not read,
 * `between 10 – 500` switched to `>` would keep a hidden 500 ceiling that no
 * label shows — and switched back, it would resurface. Every surface that sets
 * the operator goes through here so none of them can forget.
 */
export function setAmountOp(op: AmountOperator): Partial<PaymentFilters> {
  if (op === "eq" || op === "gt") {
    return { amountMax: "", amountOp: op };
  }
  if (op === "lt") {
    return { amountMin: "", amountOp: op };
  }
  return { amountOp: op };
}

// ---------------------------------------------------------------------------
// Sort
// ---------------------------------------------------------------------------

export type PaymentSortKey =
  | "amount"
  | "createdAt"
  | "finishedAt"
  | "playerEmail"
  | "status";

/**
 * Always set: a ledger always has an order, and "Unsorted" would mean fixture
 * order, which is no order anyone asked for.
 */
export type SortState = BaseSortState<PaymentSortKey>;

/**
 * Column first, then direction, in the order someone reaches for them on a
 * ledger: when, then how much, then who.
 */
export const SORT_KEYS: readonly { id: PaymentSortKey; label: string }[] = [
  { id: "createdAt", label: "Created" },
  { id: "finishedAt", label: "Finished" },
  { id: "amount", label: "Amount" },
  { id: "playerEmail", label: "Player" },
  { id: "status", label: "Status" },
];

/**
 * What a direction means for the column it applies to. "Descending" is
 * accurate and says nothing — "Newest first" says what you will see.
 */
const DIRECTION_LABELS: Record<
  PaymentSortKey,
  Record<SortDirection, string>
> = {
  amount: { asc: "Smallest first", desc: "Largest first" },
  createdAt: { asc: "Oldest first", desc: "Newest first" },
  finishedAt: { asc: "Oldest first", desc: "Newest first" },
  playerEmail: { asc: "A–Z", desc: "Z–A" },
  status: { asc: "A–Z", desc: "Z–A" },
};

export function directionLabel(
  key: PaymentSortKey,
  direction: SortDirection
): string {
  return DIRECTION_LABELS[key][direction];
}

/**
 * The direction a column takes when it is first chosen, from the menu or a
 * header. Names read forwards; dates and amounts are asked about from the
 * large end.
 */
export function defaultDirection(key: PaymentSortKey): SortDirection {
  return key === "playerEmail" || key === "status" ? "asc" : "desc";
}

export const DEFAULT_SORT: SortState = { direction: "desc", key: "createdAt" };

/** "Created (Newest first)" — the column, then what the order means for it. */
export function sortLabel(sort: SortState): string {
  const key = SORT_KEYS.find((option) => option.id === sort.key)?.label;
  return `${key} (${directionLabel(sort.key, sort.direction)})`;
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

type PaymentMatcher = (payment: Payment, filters: PaymentFilters) => boolean;

/**
 * One predicate per filter, each returning `true` when the filter is unset.
 *
 * A list rather than a single predicate with nine early returns: a filter set
 * is exactly a conjunction, and writing it as one keeps each rule readable on
 * its own and makes adding the tenth a one-line change.
 */
const MATCHERS: readonly PaymentMatcher[] = [
  (payment, filters) => {
    const query = filters.email.trim().toLowerCase();
    return !query || payment.playerEmail.toLowerCase().includes(query);
  },
  (payment, filters) =>
    filters.currencies.length === 0 ||
    filters.currencies.includes(payment.currency) ===
      (filters.currencyOp === "is"),
  (payment, filters) => filters.type === "all" || payment.type === filters.type,
  (payment, filters) =>
    filters.status === "all" || payment.status === filters.status,
  (payment, filters) =>
    filters.provider === "all" || payment.provider === filters.provider,
  (payment, filters) => matchesPlayer(payment.playerEmail, filters),
  // The timestamps are ISO, so the date half compares as a string.
  (payment, filters) =>
    !filters.createdAfter ||
    payment.createdAt.slice(0, 10) >= filters.createdAfter,
  (payment, filters) =>
    !filters.createdBefore ||
    payment.createdAt.slice(0, 10) <= filters.createdBefore,
  (payment, filters) => matchesAmount(Number(payment.amount), filters),
];

/** Case-insensitive, and blank text never narrows, whatever the operator. */
function matchesPlayer(email: string, filters: PaymentFilters): boolean {
  const query = filters.player.trim().toLowerCase();
  if (!query) {
    return true;
  }
  const value = email.toLowerCase();
  switch (filters.playerOp) {
    case "is":
      return value === query;
    case "isNot":
      return value !== query;
    case "notContains":
      return !value.includes(query);
    case "startsWith":
      return value.startsWith(query);
    case "endsWith":
      return value.endsWith(query);
    default:
      return value.includes(query);
  }
}

/** One matcher for every amount operator; an empty bound never narrows. */
function matchesAmount(amount: number, filters: PaymentFilters): boolean {
  const { amountMax: max, amountMin: min, amountOp: op } = filters;
  switch (op) {
    case "eq":
      return !min || amount === Number(min);
    case "gt":
      return !min || amount > Number(min);
    case "lt":
      return !max || amount < Number(max);
    default:
      return (!min || amount >= Number(min)) && (!max || amount <= Number(max));
  }
}

export function matchesPaymentFilters(
  payment: Payment,
  filters: PaymentFilters
): boolean {
  return MATCHERS.every((matches) => matches(payment, filters));
}

/**
 * Amounts compare as plain numbers, across currencies — so 1 BTC sorts below
 * 600 EUR. A fixture has no exchange rates to do better with; a real ledger
 * sorts on a converted reporting-currency column, or narrows to one currency
 * first (the Currency filter) so the comparison means something.
 *
 * Dates compare as strings, which is only correct because the fixture's
 * `YYYY-MM-DD HH:mm:ss` is zero-padded and fixed-width. Parse them first if
 * yours carry offsets or mixed formats.
 */
export function sortPayments(
  rows: readonly Payment[],
  sort: SortState
): Payment[] {
  const factor = sort.direction === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    if (sort.key === "amount") {
      return (Number(a.amount) - Number(b.amount)) * factor;
    }
    const left = a[sort.key];
    const right = b[sort.key];
    // A payment that has not finished has no finish time to order by, so it
    // sinks to the end in both directions rather than heading one of them —
    // "Newest first" opening on a page of dashes would answer nothing.
    if (left === null || right === null) {
      return Number(left === null) - Number(right === null);
    }
    return left.localeCompare(right) * factor;
  });
}

// ---------------------------------------------------------------------------
// The pills
// ---------------------------------------------------------------------------

export type FilterKey =
  | "amount"
  | "created"
  | "currencies"
  | "player"
  | "provider"
  | "status"
  | "type";

export interface FilterDef {
  /** The patch that resets this filter. */
  clear: Partial<PaymentFilters>;
  /**
   * What the pill reads when nothing is set. "All" suits a set of options;
   * a range is not a set, so its bounds read as "Any".
   */
  empty: string;
  key: FilterKey;
  /** The dimension, shown muted ahead of the value. */
  label: string;
  /**
   * The operator, when it is not the default. Notion's convention: `is` goes
   * unsaid — "Currency: BTC" — and only a qualifier earns words, "Currency is
   * not: BTC". Absent on filters without operators.
   */
  operator?: (filters: PaymentFilters) => string | null;
  /** The value, or `null` when the filter is unset. */
  value: (filters: PaymentFilters) => string | null;
}

/**
 * The pills a fresh table starts with: the two cuts people take first. The
 * rest are added on demand — every pill costs horizontal room, and a row that
 * always carries all six wraps before anyone has used one.
 *
 * A starting set, not a permanent one. These come off the row like any other
 * pill, so every X on the toolbar does the same thing, and `Clear all` puts
 * them back.
 */
export const DEFAULT_KEYS: readonly FilterKey[] = ["type", "status"];

export const FILTERS: readonly FilterDef[] = [
  {
    clear: { type: "all" },
    empty: "All",
    key: "type",
    label: "Action",
    value: (f) => (f.type === "all" ? null : typeLabel(f.type)),
  },
  {
    clear: { status: "all" },
    empty: "All",
    key: "status",
    label: "Status",
    value: (f) => (f.status === "all" ? null : statusLabel(f.status)),
  },
  {
    clear: { currencies: [], currencyOp: "is" },
    empty: "All",
    key: "currencies",
    label: "Currency",
    operator: (f) => (f.currencyOp === "isNot" ? "is not" : null),
    // The first selection plus a count of the rest: "BTC, +2". A bare "3"
    // says how many without saying which, and four tickers side by side stop
    // being scannable and start being a sentence.
    value: (f) => {
      if (f.currencies.length === 0) {
        return null;
      }
      return f.currencies.length === 1
        ? f.currencies[0]
        : `${f.currencies[0]}, +${f.currencies.length - 1}`;
    },
  },
  {
    clear: { provider: "all" },
    empty: "All",
    key: "provider",
    label: "Provider",
    value: (f) => (f.provider === "all" ? null : f.provider),
  },
  {
    clear: { player: "", playerOp: "contains" },
    empty: "Any",
    key: "player",
    label: "Player",
    operator: (f) =>
      f.playerOp === "contains"
        ? null
        : (PLAYER_OPERATORS.find((item) => item.value === f.playerOp)?.label ??
          null),
    value: (f) => f.player.trim() || null,
  },
  {
    clear: { createdAfter: "", createdBefore: "" },
    empty: "Any",
    key: "created",
    label: "Created",
    value: (f) => rangeValue(f.createdAfter, f.createdBefore),
  },
  {
    clear: { amountMax: "", amountMin: "", amountOp: "between" },
    empty: "Any",
    key: "amount",
    label: "Amount",
    value: (f) => amountValue(f),
  },
];

/** An open-ended range still has to say which end it is open at. */
function rangeValue(min: string, max: string): string | null {
  if (min && max) {
    return `${min} – ${max}`;
  }
  if (min) {
    return `from ${min}`;
  }
  if (max) {
    return `to ${max}`;
  }
  return null;
}

/**
 * The comparison is part of the value — "> 100" — rather than spelled out in
 * the label, because a symbol next to a number reads faster than "is greater
 * than" and the label stays the same width whichever operator is picked.
 */
function amountValue(f: PaymentFilters): string | null {
  if (f.amountOp === "between") {
    return rangeValue(f.amountMin, f.amountMax);
  }
  const bound = f.amountOp === "lt" ? f.amountMax : f.amountMin;
  if (!bound) {
    return null;
  }
  return `${AMOUNT_SYMBOLS[f.amountOp]} ${bound}`;
}

export function filterDef(key: FilterKey): FilterDef {
  const def = FILTERS.find((item) => item.key === key);
  if (!def) {
    throw new Error(`Unknown filter: ${key}`);
  }
  return def;
}

/**
 * Which pills the toolbar shows, in the order it shows them: the ones on the
 * row — the starting pair plus any added by hand, in the order they arrived —
 * then, the load-bearing term, any filter that holds a value without having
 * been asked for.
 *
 * That last group is what makes applied state impossible to hide. A filter
 * with a value and no pill is exactly the failure the old chip row existed to
 * paper over; here it cannot happen, rather than merely being tested for. It
 * is reachable through the mobile drawer, which sets filters that were never
 * added as pills.
 *
 * The ordering matters as much as the membership. Filtering `FILTERS` in
 * declaration order put each new pill in its canonical slot instead of at the
 * end — add Amount then Currency and Currency landed in front of it, nowhere
 * near the `+ Add filter` button you were just looking at.
 */
export function visibleKeys(
  filters: PaymentFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  return visibleKeysOf(FILTERS, filters, added);
}

/** Filters still available to add — the add-filter menu's contents. */
export function addableKeys(
  filters: PaymentFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  return addableKeysOf(FILTERS, filters, added);
}

/** Whether anything at all is applied, search included. */
export function hasActiveFilters(filters: PaymentFilters): boolean {
  return (
    Boolean(filters.email.trim()) ||
    FILTERS.some((def) => def.value(filters) !== null)
  );
}

// ---------------------------------------------------------------------------
// Export
// ---------------------------------------------------------------------------

const CSV_COLUMNS: readonly CsvColumn<Payment>[] = [
  ["Payment ID", (p) => p.id],
  ["Player", (p) => p.playerEmail],
  ["Amount", (p) => p.amount],
  ["Currency", (p) => p.currency],
  ["Type", (p) => p.type],
  ["Status", (p) => p.status],
  ["Provider", (p) => p.provider],
  ["Created", (p) => p.createdAt],
  ["Finished", (p) => p.finishedAt ?? ""],
];

/**
 * The rows as CSV.
 *
 * Raw values, not the table's display: the provider's amount string rather
 * than `10,000.00` (whose comma a spreadsheet would split or misread), the
 * enum ids rather than labels, an empty cell rather than a dash for a payment
 * that has not finished. The toolbar passes every row the filters and sort
 * produced, not the current page — an export of ten rows out of eighteen is a
 * bug report waiting to happen.
 */
export function toPaymentsCsv(rows: readonly Payment[]): string {
  return toCsv(CSV_COLUMNS, rows);
}

// ---------------------------------------------------------------------------
// URL
// ---------------------------------------------------------------------------

export const PAGE_SIZES = [10, 20, 30, 50] as const;
export const DEFAULT_PAGE_SIZE = 10;

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const DECIMAL = /^\d+(\.\d+)?$/;

/** The table's query as URL parameters, defaults left out. */
export function paymentsToParams(
  query: DataTableQuery<PaymentFilters, PaymentSortKey>
): Record<string, string> {
  const f = query.filters;
  return {
    q: f.email,
    type: f.type === "all" ? "" : f.type,
    status: f.status === "all" ? "" : f.status,
    provider: f.provider === "all" ? "" : f.provider,
    currency: f.currencies.join(","),
    currencyOp:
      f.currencies.length > 0 && f.currencyOp === "isNot" ? "isNot" : "",
    player: f.player,
    playerOp: f.player && f.playerOp !== "contains" ? f.playerOp : "",
    from: f.createdAfter,
    to: f.createdBefore,
    amountOp:
      (f.amountMin || f.amountMax) && f.amountOp !== "between"
        ? f.amountOp
        : "",
    min: f.amountMin,
    max: f.amountMax,
    sort: sortToParam(query.sort, DEFAULT_SORT),
    ...pageToParams(query.pageIndex, query.pageSize, DEFAULT_PAGE_SIZE),
  };
}

/** The inverse, validating every value; anything unrecognised is dropped. */
export function paymentsFromParams(
  params: URLSearchParams
): Partial<DataTableQuery<PaymentFilters, PaymentSortKey>> {
  const date = (key: string) => {
    const value = params.get(key) ?? "";
    return ISO_DATE.test(value) ? value : "";
  };
  const decimal = (key: string) => {
    const value = params.get(key) ?? "";
    return DECIMAL.test(value) ? value : "";
  };
  const currencies = (params.get("currency") ?? "")
    .split(",")
    .filter((value): value is Currency =>
      CURRENCIES.includes(value as Currency)
    );

  return {
    filters: {
      amountMax: decimal("max"),
      amountMin: decimal("min"),
      amountOp: oneOf(params.get("amountOp"), AMOUNT_OPERATORS, "between"),
      createdAfter: date("from"),
      createdBefore: date("to"),
      currencies,
      currencyOp: oneOf(params.get("currencyOp"), ["is", "isNot"], "is"),
      email: params.get("q") ?? "",
      player: params.get("player") ?? "",
      playerOp: oneOf(
        params.get("playerOp"),
        PLAYER_OPERATORS.map((op) => op.value),
        "contains"
      ),
      provider: oneOf(params.get("provider"), PROVIDER_OPTIONS, "all"),
      status: oneOf(params.get("status"), STATUS_OPTIONS, "all"),
      type: oneOf(params.get("type"), TYPE_OPTIONS, "all"),
    },
    sort: sortFromParam(
      params.get("sort"),
      SORT_KEYS.map((key) => key.id)
    ),
    ...pageFromParams(params, PAGE_SIZES),
  };
}

"use client";

import { XIcon } from "lucide-react";
import type { KeyboardEvent, ReactNode } from "react";
import { useRef, useSyncExternalStore } from "react";
import { X_SWAP } from "@/components/filter-trigger";
import { cn } from "@/lib/utils";

export interface ShellControls {
  /** Backspace / Delete on the trigger removes the filter. */
  keyDown: (event: KeyboardEvent<HTMLElement>) => void;
  remove: () => void;
}

/**
 * Wraps a pill's trigger with the X that swaps in for its chevron.
 *
 * The X is the trigger's sibling, not its child: a button inside a button is
 * invalid HTML and leaves the inner one unreachable to assistive tech. It sits
 * absolutely over the chevron's 16px slot — `end-3` is the `sm` button's `px-3`
 * — so showing it changes nothing about the pill's width.
 *
 * It is out of the tab order. Keyboard users have Backspace on the trigger,
 * which is announced through `aria-keyshortcuts`; one stop per pill keeps
 * tabbing along a row of eight pills at eight stops rather than sixteen.
 *
 * Every pill has one, the starting pair included, so the X means the same
 * thing wherever it appears. The label says which filter, "Remove Provider
 * filter", for the same reason the row actions do.
 */
export function PillShell({
  children,
  label,
  onRemove,
}: {
  children: (controls: ShellControls) => ReactNode;
  /** The filter's dimension, for the X's accessible name. */
  label: string;
  /** Handed the pill's trigger, so focus can move before it unmounts. */
  onRemove: (trigger: HTMLElement | null) => void;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const remove = () =>
    onRemove(
      ref.current?.querySelector<HTMLElement>("[data-filter-pill]") ?? null
    );
  const keyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (
      (event.key === "Backspace" || event.key === "Delete") &&
      !event.defaultPrevented &&
      event.currentTarget.getAttribute("aria-expanded") !== "true"
    ) {
      event.preventDefault();
      remove();
    }
  };

  return (
    <span className="group/pill relative inline-flex" ref={ref}>
      {children({ keyDown, remove })}
      <button
        aria-label={`Remove ${label} filter`}
        className={cn(
          "absolute end-3 top-1/2 z-10 grid size-4 -translate-y-1/2 cursor-pointer place-items-center rounded-sm text-muted-foreground before:absolute before:-inset-1 hover:bg-foreground/10 hover:text-foreground",
          X_SWAP
        )}
        data-filter-remove=""
        onClick={remove}
        tabIndex={-1}
        type="button"
      >
        <XIcon className="size-3.5" />
      </button>
    </span>
  );
}

/**
 * The pill's value, in its own slot so the set and unset cases are the same
 * element rather than a span and a bare text node — which is what lets a test
 * compare their colours at all.
 */
export function PillValue({
  empty,
  value,
}: {
  empty: string;
  value: string | null;
}) {
  return (
    <span
      className={value === null ? "font-normal text-muted-foreground" : ""}
      data-pill-value=""
    >
      {value ?? empty}
    </span>
  );
}

const HOVERLESS = "(hover: none)";

/**
 * Whether the device has no hover, and so never sees the X swap.
 *
 * Local to the block rather than `@keystoneui/react/hooks`: blocks install as
 * copies, and that subpath has no registry item to land at. The usual objection
 * to a media-query hook — it has to guess on the server and flip after
 * hydration — does not bite here, because its only callers render inside a
 * popup, which mounts on open, long after hydration.
 */
export function useHoverless(): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const query = matchMedia(HOVERLESS);
      query.addEventListener("change", onChange);
      return () => query.removeEventListener("change", onChange);
    },
    () => matchMedia(HOVERLESS).matches,
    () => false
  );
}

/**
 * How much of the result set is on screen.
 *
 * Shared between this block's two tables, which asked the same question with
 * the same arithmetic and differed only in the noun.
 *
 * It is not what the pagination status says: `Page 2 of 2` reads the same
 * whether that page holds ten rows or the three left over. Nor is it the
 * selection count — `SelectionBar` already states that, at every width, where
 * `TablePaginationInfo` is `hidden lg:block`.
 *
 * Deliberately a block file rather than a library prop. `TablePaginationInfo`
 * already accepts `children`, which is the composition answer, and the whole
 * of the rest is two lines of arithmetic and a plural.
 */
export function ResultSummary({
  noun,
  pageIndex,
  pageSize,
  rowCount,
  totalCount,
}: {
  /** Singular and plural, because English will not derive one from the other. */
  noun: [string, string];
  pageIndex: number;
  pageSize: number;
  rowCount: number;
  totalCount: number;
}) {
  if (totalCount === 0) {
    return null;
  }

  const first = pageIndex * pageSize + 1;
  const last = pageIndex * pageSize + rowCount;

  return (
    <>
      Showing {first}–{last} of {totalCount}{" "}
      {totalCount === 1 ? noun[0] : noun[1]}
    </>
  );
}

"use client";

import { cn } from "@/lib/utils";

export interface SeriesDef {
  /** Slot 1-5 in the chart ramp. Omit to take the position in the list. */
  color?: number;
  key: string;
  label: string;
  /**
   * Use a named token instead of a ramp slot, e.g. `"muted-foreground"`.
   *
   * The escape hatch matters: an "Other" or "Unclassified" band is not a
   * category, and giving it a categorical hue claims one exists where there is
   * only missing evidence.
   */
  token?: string;
}

/**
 * The single place a series' colour is decided.
 *
 * Both the mark and the legend swatch resolve through this, so they cannot
 * disagree — a legend that says one thing while the band says another is worse
 * than no legend.
 */
export function seriesColor(item: SeriesDef, index: number): string {
  if (item.token) {
    return `var(--${item.token})`;
  }
  return `var(--chart-${item.color ?? (index % 5) + 1})`;
}

interface SeriesLegendProps {
  hidden: ReadonlySet<string>;
  onToggle: (key: string) => void;
  series: readonly SeriesDef[];
}

export function SeriesLegend({ hidden, onToggle, series }: SeriesLegendProps) {
  const visible = series.filter((item) => !hidden.has(item.key)).length;

  return (
    <ul className="flex flex-wrap items-center gap-x-4 gap-y-1">
      {/* Rendered from `series`, never from recharts' payload: the payload
          drops hidden entries, which would give you a chart you can narrow and
          then never widen again. */}
      {series.map((item, index) => {
        const off = hidden.has(item.key);
        // An empty chart is not a view of anything, and a reader cannot tell it
        // from "no data" — so the last visible series refuses to switch off.
        const locked = !off && visible === 1;

        return (
          <li key={item.key}>
            <button
              aria-pressed={!off}
              className={cn(
                "inline-flex cursor-pointer items-center gap-1.5 rounded-sm text-xs transition-colors focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2",
                off
                  ? "text-muted-foreground line-through opacity-60"
                  : "text-foreground",
                locked && "cursor-not-allowed"
              )}
              disabled={locked}
              onClick={() => onToggle(item.key)}
              title={
                locked ? "At least one series has to stay visible" : undefined
              }
              type="button"
            >
              <span
                aria-hidden="true"
                className="size-2.5 shrink-0 rounded-[2px]"
                style={{ backgroundColor: seriesColor(item, index) }}
              />
              {item.label}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import { Skeleton } from "@/components/ui/skeleton";
import { TableCell, TableRow } from "@/components/ui/table";

/**
 * Placeholder rows while the table's request is in flight.
 *
 * Built to the real rows' height so nothing moves when the data lands: the
 * actions cell holds a 32px box — the `icon-sm` trigger the real row has — and
 * a two-line column (a name over an email) gets two bars at the real lines'
 * heights. The count is the previous page's, so a refetch does not
 * collapse the table to a single row and spring back.
 *
 * Hidden from assistive tech: the table's `aria-busy` is what says "loading".
 * Grey bars announced cell by cell would be noise.
 */
export function SkeletonRows({
  checkbox = false,
  columns,
  count,
  twoLine,
}: {
  checkbox?: boolean;
  /** Data columns between the checkbox and the actions. */
  columns: number;
  count: number;
  /** The data column, by index, that holds two lines of text. */
  twoLine?: number;
}) {
  // Placeholders have no identity of their own; position is the only key.
  return Array.from({ length: count }, (_row, row) => (
    // biome-ignore lint/suspicious/noArrayIndexKey: placeholders, keyed by slot
    <TableRow aria-hidden data-skeleton-row="" key={row}>
      {checkbox ? (
        <TableCell>
          <Skeleton className="size-4" />
        </TableCell>
      ) : null}
      {Array.from({ length: columns }, (_column, column) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: placeholders, keyed by slot
        <TableCell key={column}>
          {column === twoLine ? (
            <div className="flex flex-col">
              <div className="flex h-5 items-center">
                <Skeleton className="h-3.5 w-28" />
              </div>
              <div className="flex h-4 items-center">
                <Skeleton className="h-3 w-40" />
              </div>
            </div>
          ) : (
            <div className="flex h-5 items-center">
              {/* Varied widths so the column does not read as a grid of
                  identical bricks. */}
              <Skeleton className={WIDTHS[(row + column) % WIDTHS.length]} />
            </div>
          )}
        </TableCell>
      ))}
      <TableCell>
        <div className="size-8" />
      </TableCell>
    </TableRow>
  ));
}

const WIDTHS = ["h-3.5 w-24", "h-3.5 w-16", "h-3.5 w-20", "h-3.5 w-12"];

"use client";

import { ArrowDownIcon, ArrowUpDownIcon, ArrowUpIcon } from "lucide-react";
import type { ReactNode } from "react";
import {
  directionsFor,
  type SortDirection,
  type SortState,
} from "@/components/sort";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { TableHead, TableSortButton } from "@/components/ui/table";

const DIRECTION_ICON = { asc: ArrowUpIcon, desc: ArrowDownIcon } as const;

/**
 * The toolbar's Sort menu: which column, then which way.
 *
 * Two radio groups rather than every column × direction pair, so flipping the
 * direction does not mean finding the column again. A new column takes its
 * natural direction, and the direction list leads with it, so the common pick
 * is always the first one. The directions are named for the column —
 * `Newest first`, `A–Z` — because "ascending" says nothing about what you will
 * see.
 *
 * It writes the same `sort` the column headers do, so a header click moves this
 * menu's check and the other way round, with no syncing code.
 */
export function SortMenu<K extends string>({
  defaultDirection,
  directionLabel,
  keys,
  onSortChange,
  sort,
}: {
  defaultDirection: (key: K) => SortDirection;
  directionLabel: (key: K, direction: SortDirection) => string;
  keys: readonly { id: K; label: string }[];
  onSortChange: (sort: SortState<K>) => void;
  sort: SortState<K>;
}) {
  const label = keys.find((option) => option.id === sort.key)?.label ?? "Sort";

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="sm" variant="outline" />}>
        <ArrowUpDownIcon />
        <span className="font-normal text-muted-foreground">Sort:</span>
        {label}
        <span className="font-normal text-muted-foreground">
          ({directionLabel(sort.key, sort.direction)})
        </span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-52">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Sort by</DropdownMenuLabel>
          <DropdownMenuRadioGroup
            onValueChange={(value) => {
              const key = value as K;
              onSortChange({ direction: defaultDirection(key), key });
            }}
            value={sort.key}
          >
            {keys.map((option) => (
              <DropdownMenuRadioItem key={option.id} value={option.id}>
                {option.label}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuGroup>
          <DropdownMenuRadioGroup
            onValueChange={(value) =>
              onSortChange({ direction: value as SortDirection, key: sort.key })
            }
            value={sort.direction}
          >
            {directionsFor(defaultDirection(sort.key)).map((direction) => {
              const Icon = DIRECTION_ICON[direction];
              return (
                <DropdownMenuRadioItem key={direction} value={direction}>
                  <Icon />
                  {directionLabel(sort.key, direction)}
                </DropdownMenuRadioItem>
              );
            })}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * A sortable column header.
 *
 * Clicking an inactive column sorts it in its natural direction — the same
 * `defaultDirection` the Sort menu uses, so a header and the menu agree on
 * what picking a column means. Clicking the active one flips it. There is no
 * third, unsorted click: these tables always have an order.
 *
 * Only on columns that sort. A column that does not passes no `sortDirection`
 * to its `TableHead` at all — `null` would claim it sorts and is merely
 * inactive, and put `aria-sort` on a header that does nothing.
 */
export function SortableHead<K extends string>({
  children,
  className,
  columnKey,
  defaultDirection,
  numeric,
  onSortChange,
  sort,
}: {
  children: ReactNode;
  className?: string;
  columnKey: K;
  defaultDirection: (key: K) => SortDirection;
  numeric?: boolean;
  onSortChange: (sort: SortState<K>) => void;
  sort: SortState<K>;
}) {
  const active = sort.key === columnKey;
  const direction = active ? sort.direction : null;
  const flipped: SortDirection = sort.direction === "asc" ? "desc" : "asc";

  return (
    <TableHead
      className={className}
      numeric={numeric}
      sortDirection={direction}
    >
      <TableSortButton
        direction={direction}
        onClick={() =>
          onSortChange({
            direction: active ? flipped : defaultDirection(columnKey),
            key: columnKey,
          })
        }
      >
        {children}
      </TableSortButton>
    </TableHead>
  );
}

/** Sort state shared by both tables, the Sort menu and the column headers. */

export type SortDirection = "asc" | "desc";

export interface SortState<K extends string> {
  direction: SortDirection;
  key: K;
}

/** Both directions, the column's natural one first — the order the menu lists. */
export function directionsFor(natural: SortDirection): SortDirection[] {
  return natural === "asc" ? ["asc", "desc"] : ["desc", "asc"];
}

import type { SortDirection, SortState } from "@/components/sort";

/**
 * Reading a table's query back out of a URL.
 *
 * A URL is input someone can type, so every reader here validates and falls
 * back rather than trusting it: `?status=bogus` opens the table unfiltered,
 * not broken. Writers leave defaults out, so an untouched table has a clean
 * URL and a shared link carries only what was changed.
 */

/** `value` if it is one of `allowed`, otherwise `fallback`. */
export function oneOf<T extends string>(
  value: string | null,
  allowed: readonly T[],
  fallback: T
): T {
  return allowed.includes(value as T) ? (value as T) : fallback;
}

/** `amount.desc` — the column and the way, in one readable parameter. */
export function sortToParam<K extends string>(
  sort: SortState<K>,
  fallback: SortState<K>
): string {
  return sort.key === fallback.key && sort.direction === fallback.direction
    ? ""
    : `${sort.key}.${sort.direction}`;
}

export function sortFromParam<K extends string>(
  value: string | null,
  keys: readonly K[]
): SortState<K> | undefined {
  const [key, direction] = (value ?? "").split(".");
  if (
    !(keys.includes(key as K) && (direction === "asc" || direction === "desc"))
  ) {
    return;
  }
  return { direction: direction as SortDirection, key: key as K };
}

/** One-based in the URL, because that is what the footer says. */
export function pageToParams(
  pageIndex: number,
  pageSize: number,
  defaultSize: number
): { page: string; size: string } {
  return {
    page: pageIndex > 0 ? String(pageIndex + 1) : "",
    size: pageSize === defaultSize ? "" : String(pageSize),
  };
}

export function pageFromParams(
  params: URLSearchParams,
  sizes: readonly number[]
): { pageIndex?: number; pageSize?: number } {
  const page = Number(params.get("page"));
  const size = Number(params.get("size"));
  return {
    pageIndex: Number.isInteger(page) && page > 1 ? page - 1 : undefined,
    pageSize: sizes.includes(size) ? size : undefined,
  };
}

"use client";

import { useEffect, useMemo, useState } from "react";
import type { SortState } from "@/components/sort";

/**
 * Everything a filterable, sortable, paged, selectable table holds, for both of
 * this block's tables.
 *
 * One hook rather than two copies of the same dozen `useState`s, so the users
 * and payments tables cannot drift apart in how they reset a page or keep a
 * selection. What differs — the rows, the filter vocabulary, how a row matches
 * and sorts — comes in through `config`.
 */
export interface DataTableConfig<Row, F, K extends string, S extends string> {
  /** A filter's reset patch, for removing its pill. */
  clearFor: (key: K) => Partial<F>;
  /** The pills on a fresh row; `Clear all` puts these back. */
  defaultKeys: readonly K[];
  defaultPageSize: number;
  defaultSort: SortState<S>;
  emptyFilters: F;
  /**
   * How long the stand-in request takes. The rows are local, so without one
   * the loading state would never be seen — a real table swaps
   * `useSimulatedFetch` for its data layer and keeps the rest.
   */
  latency?: number;
  matches: (row: Row, filters: F) => boolean;
  rows: readonly Row[];
  sortRows: (rows: readonly Row[], sort: SortState<S>) => Row[];
}

/** The part of the state a URL can carry, and a request would send. */
export interface DataTableQuery<F, S extends string> {
  filters: F;
  pageIndex: number;
  pageSize: number;
  sort: SortState<S>;
}

export interface DataTableResult<Row> {
  /** Every row the filters and sort produce — what Export writes. */
  all: Row[];
  /** The current page of `all`. */
  page: Row[];
  pageCount: number;
  total: number;
}

export function useDataTable<
  Row extends { id: string },
  F,
  K extends string,
  S extends string,
  C extends string = string,
>(config: DataTableConfig<Row, F, K, S>) {
  const [filters, setFilters] = useState<F>(config.emptyFilters);
  const [sort, setSortState] = useState(config.defaultSort);
  const [pageIndex, setPageIndex] = useState(0);
  const [pageSize, setPageSizeState] = useState(config.defaultPageSize);
  // Which pills are on the row: the starting set, plus any added by hand,
  // minus any removed. A filter holding a value shows its pill regardless, so
  // this only decides which empty ones are on show.
  const [added, setAdded] = useState<K[]>(() => [...config.defaultKeys]);
  // Kept across pages and filters: selecting rows on page one, then page two,
  // then exporting is the whole point of a selection that outlives a page.
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const [hiddenColumns, setHiddenColumns] = useState<ReadonlySet<C>>(new Set());

  const query: DataTableQuery<F, S> = { filters, pageIndex, pageSize, sort };
  const { loading, result } = useSimulatedFetch(
    query,
    () => run(config, query),
    config.latency ?? 300,
    EMPTY_RESULT as DataTableResult<Row>
  );

  // A page that no longer exists — `?page=9` on a link, or the last row of the
  // last page deleted elsewhere — snaps to the last page that does.
  useEffect(() => {
    if (!loading && pageIndex > result.pageCount - 1) {
      setPageIndex(result.pageCount - 1);
    }
  }, [loading, pageIndex, result.pageCount]);

  // Every change that can shrink the result goes back to the first page:
  // page 2 of the unfiltered list usually does not exist once a filter is on,
  // and "Page 2 of 1" with no rows looks broken.
  const patchFilters = (patch: Partial<F>) => {
    setFilters((current) => ({ ...current, ...patch }));
    setPageIndex(0);
  };

  return {
    added,
    addFilter: (key: K) =>
      setAdded((current) =>
        current.includes(key) ? current : [...current, key]
      ),
    clearFilters: () => {
      setFilters(config.emptyFilters);
      setAdded([...config.defaultKeys]);
      setPageIndex(0);
    },
    clearSelection: () => setSelected(new Set()),
    filters,
    hiddenColumns,
    loading,
    pageIndex,
    pageSize,
    patchFilters,
    query,
    removeFilter: (key: K) => {
      patchFilters(config.clearFor(key));
      setAdded((current) => current.filter((item) => item !== key));
    },
    /** Applies a query read from somewhere else — the URL, on load. */
    restore: (next: Partial<DataTableQuery<F, S>>) => {
      if (next.filters) {
        setFilters(next.filters);
      }
      if (next.sort) {
        setSortState(next.sort);
      }
      if (next.pageSize) {
        setPageSizeState(next.pageSize);
      }
      if (next.pageIndex !== undefined) {
        setPageIndex(next.pageIndex);
      }
    },
    result,
    selected,
    setPageIndex,
    setPageSize: (size: number) => {
      setPageSizeState(size);
      // Page 3 of a 5-per-page list does not exist at 50 per page.
      setPageIndex(0);
    },
    setSort: (next: SortState<S>) => {
      setSortState(next);
      setPageIndex(0);
    },
    sort,
    toggleColumn: (id: C) =>
      setHiddenColumns((current) => toggled(current, id)),
    /** Selects or clears every row on the current page. */
    togglePage: (checked: boolean) =>
      setSelected((current) => {
        const next = new Set(current);
        for (const row of result.page) {
          if (checked) {
            next.add(row.id);
          } else {
            next.delete(row.id);
          }
        }
        return next;
      }),
    toggleRow: (id: string) => setSelected((current) => toggled(current, id)),
  };
}

function toggled<T>(set: ReadonlySet<T>, item: T): ReadonlySet<T> {
  const next = new Set(set);
  if (next.has(item)) {
    next.delete(item);
  } else {
    next.add(item);
  }
  return next;
}

/** What a server would do with the query: filter, sort, count, slice. */
function run<Row, F, K extends string, S extends string>(
  config: DataTableConfig<Row, F, K, S>,
  query: DataTableQuery<F, S>
): DataTableResult<Row> {
  const all = config.sortRows(
    config.rows.filter((row) => config.matches(row, query.filters)),
    query.sort
  );
  const start = query.pageIndex * query.pageSize;
  return {
    all,
    page: all.slice(start, start + query.pageSize),
    pageCount: Math.max(1, Math.ceil(all.length / query.pageSize)),
    total: all.length,
  };
}

const EMPTY_RESULT: DataTableResult<never> = {
  all: [],
  page: [],
  pageCount: 1,
  total: 0,
};

/**
 * Answers a query after `latency`, the way a request would.
 *
 * Each change restarts the wait, so typing in search settles once rather than
 * once per keystroke — the debounce a real search field needs, for free.
 * While waiting, the last answer stays in hand: the pagination and summary keep
 * describing the rows that were there rather than collapsing to zero, and the
 * table body shows skeleton rows in their place.
 *
 * It starts out loading, on the server too, so the first paint is the
 * skeleton rather than a flash of the unfiltered table before a URL's filters
 * apply.
 */
function useSimulatedFetch<Q, R>(
  query: Q,
  answer: () => R,
  latency: number,
  initial: R
): { loading: boolean; result: R } {
  const key = JSON.stringify(query);
  const [settled, setSettled] = useState<{ key: string; result: R } | null>(
    null
  );
  // `answer` is a fresh closure each render; the key is what identifies it.
  // biome-ignore lint/correctness/useExhaustiveDependencies: keyed on `key`
  const pending = useMemo(answer, [key]);

  useEffect(() => {
    const timer = setTimeout(
      () => setSettled({ key, result: pending }),
      latency
    );
    return () => clearTimeout(timer);
  }, [key, latency, pending]);

  return {
    loading: settled?.key !== key,
    result: settled?.result ?? initial,
  };
}

